  "memory_notes": [
    {
      "key": "trajectory_position_is_not_sensorimotor_state",
      "title": "位置轨迹不等于感觉运动状态",
      "kind": "correction",
      "mastery": "used",
      "understanding": "坐标序列描述跟踪对象的位置，不直接测量感觉输入、姿态、受力、意图、干预或行为类别。本轮核验支持将行为阶段解释限制在现有证据范围内；这不证明相关行为不存在。",
      "conditions": "限于所给坐标、元数据与核验报告；追踪身份稳定性、任务和追踪分值语义未知。",
      "example": "R07 窗口可描述为位置变化；单凭坐标不能判定追随、转弯或感觉引导。",
      "open_questions": [
        "没有独立行为标签时，哪些轨迹描述最稳健？",
        "当前记录中的追踪标签是否保持稳定？",
        "无法由当前材料解释行为阶段或机制。"
      ],
